"""Generated byte streams exercise copy budgets; no engine or character data."""
import io
import shutil
import tempfile
from pathlib import Path
from threading import Event
import unittest

from ucc.core.errors import ProjectStorageError
from ucc.jobs.skin_material_preparation import _BudgetCancel
from ucc.jobs.unreal_export_payload import _CopyReader


class UnrealPayloadIOTests(unittest.TestCase):
    def test_copy_stops_at_cancel_or_deadline_without_leaking_next_chunk(self):
        chunk = 1024 * 1024

        class Reader:
            def __init__(self, stream, after_read):
                self.stream, self.after_read = stream, after_read
                self.name, self.reads = stream.name, 0

            def read(self, size):
                self.reads += 1
                data = self.stream.read(size)
                self.after_read()
                return data

        class Writer(io.BytesIO):
            def __init__(self, after_write):
                super().__init__()
                self.after_write = after_write

            def write(self, data):
                count = super().write(data)
                self.after_write()
                return count

        with tempfile.TemporaryDirectory() as directory:
            source = Path(directory) / 'synthetic.bin'
            source.write_bytes(b'a' * chunk + b'b' * chunk)
            for mode in ('pre_cancel', 'during_read', 'after_write', 'deadline_during_read'):
                with self.subTest(mode=mode), source.open('rb') as stream:
                    user = Event()
                    budget = _BudgetCancel(user, float('inf'))
                    if mode == 'pre_cancel':
                        user.set()

                    def after_read():
                        if mode == 'during_read':
                            user.set()
                        elif mode == 'deadline_during_read':
                            budget.deadline = 0.0

                    reader = Reader(stream, after_read)
                    target = Writer(user.set if mode == 'after_write' else lambda: None)
                    with self.assertRaises(ProjectStorageError):
                        shutil.copyfileobj(_CopyReader(reader, budget), target, length=chunk)
                    self.assertEqual(reader.reads, 0 if mode == 'pre_cancel' else 1)
                    # An interrupted read is discarded before the copy primitive writes it.
                    self.assertEqual(target.getvalue(), b'a' * chunk if mode == 'after_write' else b'')
                    self.assertEqual(stream.tell(), 0 if mode == 'pre_cancel' else chunk)


if __name__ == '__main__':
    unittest.main()
